#!/bin/bash
NT_BOX=${NT_BOX:-/home/ntbuild}  # box root used in the study; set NT_BOX to run elsewhere
# usage (as ntbuild on the box): [PAR=5] [SLOTFILE=F] [MEMCHK_GB=G] run_cover3.sh TAG [PARSE_MEMGB] [LEAF_MEMGB]
# Builds the BerryOpt modules of covers/TAG (generated by gen_cover.py) with lrun3.sh (PAR jobs at once, slots from SLOTFILE;
# in total, shared slots): Tree, then Parse and the leaf batches, then All, then the driver-style check F2_TAG.
# Resumable: a module whose log ends with rc=0 and whose olean exists is skipped.
set -u
TAG=${1:?}; PMEM=${2:-48}; LMEM=${3:-24}
W=${NT_BOX}/work_parse_once
D=$W/covers/$TAG
cd $D || exit 2
export LIB=$W/lib3
done_mod() { [ -f "$1.olean" ] && grep -q '^rc=0$' "$1.log" 2>/dev/null; }
running_mod() { pgrep -f "bin/lean .* $1.lean" > /dev/null; }
log() { echo "$(date -u +%FT%TZ) $TAG $*" >> $D/run_cover.log; }
log "start pmem=$PMEM lmem=$LMEM"
if ! done_mod BO_${TAG}_Tree; then OLEAN=1 MEMGB=16 TO=1800 $W/scripts/lrun3.sh $D BO_${TAG}_Tree; fi
done_mod BO_${TAG}_Tree || { log "tree failed"; exit 1; }
todo=()
done_mod BO_${TAG}_Parse || running_mod BO_${TAG}_Parse || todo+=("P BO_${TAG}_Parse")
while read -r m; do [ -n "$m" ] && ! done_mod $m && ! running_mod $m && todo+=("L $m"); done < batches.txt
log "todo ${#todo[@]}"
export D PMEM LMEM W SLOTFILE MEMCHK_GB
printf '%s\n' "${todo[@]}" | xargs -P ${PAR:-5} -L 1 bash -c 'if [ "$0" = P ]; then OLEAN=1 MEMGB=$PMEM TO=7200 $W/scripts/lrun3.sh $D $1; else OLEAN=1 MEMGB=$LMEM TO=14400 $W/scripts/lrun3.sh $D $1; fi'
# wait for modules started elsewhere (an earlier scheduler) to end
while pgrep -f "bin/lean .* BO_${TAG}_" > /dev/null; do sleep 30; done
bad=0
done_mod BO_${TAG}_Parse || { log "parse not done"; bad=1; }
while read -r m; do [ -n "$m" ] && ! done_mod $m && { log "leaf module $m not done"; bad=1; }; done < batches.txt
[ $bad = 0 ] || { log "incomplete"; exit 1; }
if ! done_mod BO_${TAG}_All; then OLEAN=1 MEMGB=32 TO=7200 $W/scripts/lrun3.sh $D BO_${TAG}_All; fi
done_mod BO_${TAG}_All || { log "assembly failed"; exit 1; }
MEMGB=32 TO=3600 $W/scripts/lrun3.sh $D F2_${TAG}
log "F2: $(grep -o 'PROVED `[^`]*`\|FAILED `[^`]*`' F2_${TAG}.log | head -1) $(tail -1 F2_${TAG}.log)"
log "end"
